// ── Helpers ────────────────────────────────────────────────────────────────────
function normalize(s: string) {
  return (s || "").toLowerCase();
}

function queryTokens(query: string): string[] {
  return normalize(query)
    .split(/[^a-z0-9.-]+/g)
    .map((t) => t.trim())
    .filter((t) => t.length >= 3);
}

function relevanceScore(query: string, text: string): number {
  const q = normalize(query);
  const t = normalize(text);
  if (!q || !t) return 0;
  if (t.includes(q)) return 100;
  const toks = queryTokens(query);
  if (!toks.length) return 0;
  let hits = 0;
  for (const tok of toks) if (t.includes(tok)) hits++;
  return Math.round((hits / toks.length) * 100);
}

function hostOf(url: string) {
  try { return new URL(url).hostname.replace(/^www\./, ""); } catch { return ""; }
}

// ── Proxy health tracker — auto-heals by skipping dead proxies ───────────────
const PROXY_HEALTH_KEY = "tl_proxy_health";
type ProxyHealth = Record<string, { ok: boolean; failedAt: number; failures: number }>;

function getProxyHealth(): ProxyHealth {
  try { return JSON.parse(localStorage.getItem(PROXY_HEALTH_KEY) || "{}"); } catch { return {}; }
}
function markProxy(url: string, ok: boolean) {
  const h = getProxyHealth();
  const existing = h[url] || { ok: true, failedAt: 0, failures: 0 };
  h[url] = ok ? { ok: true, failedAt: 0, failures: 0 }
               : { ok: false, failedAt: Date.now(), failures: (existing.failures || 0) + 1 };
  try { localStorage.setItem(PROXY_HEALTH_KEY, JSON.stringify(h)); } catch {}
}
function isProxyHealthy(url: string): boolean {
  const h = getProxyHealth();
  const entry = h[url];
  if (!entry || entry.ok) return true;
  // Retry after: 2min for first fail, 5min for repeated, 15min for 5+ failures
  const retry = entry.failures >= 5 ? 15*60000 : entry.failures >= 2 ? 5*60000 : 2*60000;
  if (Date.now() - entry.failedAt > retry) return true; // healed — retry
  return false;
}

