// ── Search engine watchdog (every 10s) ────────────────────────────────────────
// Goal: keep search working even if a provider or proxy goes down.
let searchWatchdogStarted = false;
function startSearchWatchdog() {
  if (searchWatchdogStarted) return;
  searchWatchdogStarted = true;

  const ddgPing = `https://api.duckduckgo.com/?q=threatlens+healthcheck&format=json&no_redirect=1&no_html=1&skip_disambig=1`;
  const searxPing = (base: string) =>
    `${base}/search?q=${encodeURIComponent("threatlens healthcheck")}&format=json&language=en&categories=news,it,general&time_range=month`;

  const tick = async () => {
    // 1) Ensure at least one proxy can reach DDG API (prevents CORS failures)
    for (const proxy of healthyProxies()) {
      const proxyUrl = proxy.endsWith("=") ? `${proxy}${encodeURIComponent(ddgPing)}` : `${proxy}${ddgPing}`;
      const ok = !!(await fetchHtml(proxyUrl, 6000));
      markProxy(proxy, ok);
      if (ok) break;
    }

    // 2) Touch a couple SearXNG instances to keep a "healthy set"
    const candidates = SEARXNG.slice(0, 4);
    await Promise.allSettled(candidates.map(async (base) => {
      const url = searxPing(base);
      // Use our proxy to avoid CORS restrictions.
      const proxyUrl = `${OWN_PROXY}${encodeURIComponent(url)}`;
      const ok = !!(await fetchHtml(proxyUrl, 6000));
      markProxy(base, ok);
    }));
  };

  // Run immediately, then every 10 seconds.
  tick();
  setInterval(tick, 10_000);
}

async function fetchHtml(url: string, timeout = 12000): Promise<string> {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), timeout);
    const res = await fetch(url, { signal: ctrl.signal });
    clearTimeout(t);
    return res.ok ? await res.text() : "";
  } catch { return ""; }
}

async function fetchViaProxy(url: string, timeout = 8000): Promise<string> {
  const proxies = healthyProxies(); // uses ALL_PROXIES including OWN_PROXY
  for (const proxy of proxies) {
    const proxyUrl = proxy.endsWith("=") ? `${proxy}${encodeURIComponent(url)}` : `${proxy}${url}`;
    const result = await fetchHtml(proxyUrl, timeout);
    if (result) { markProxy(proxy, true); return result; }
    markProxy(proxy, false);
  }
  return "";
}

// ── 1. Fast web search: Google News RSS + Bing News RSS (no key, instant) ─────
// RSS feeds are tiny XML files — 10-50x faster than scraping full HTML pages.
// Both are free, no API key, and return real news results worldwide.

function parseRSS(xml: string, badge: string, limit = 10): WebResult[] {
  const items: WebResult[] = [];
  const itemRe = /<item[\s\S]*?<\/item>/gi;
  let m: RegExpExecArray | null;
  let pos = 1;
  while ((m = itemRe.exec(xml)) !== null && items.length < limit) {
    const block = m[0];
    const title   = strip(getTag(block, "title"));
    const rawLink = strip(getTag(block, "link")) || strip(getTag(block, "guid"));
    const snippet = strip(getTag(block, "description")).slice(0, 200);
    if (!title || !rawLink) continue;
    // Google News links are redirects — extract real URL
    let link = rawLink;
    if (link.includes("news.google.com") && link.includes("url=")) {
      const u = link.match(/url=([^&]+)/);
      if (u) link = decodeURIComponent(u[1]);
    }
    if (!link.startsWith("http")) continue;
    items.push({ position: pos++, title, link, snippet, source: hostOf(link), badge });
  }
  return items;
}

function getTag(xml: string, tag: string): string {
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, "i");
  const m = xml.match(re);
  return m ? m[1].replace(/^<!\[CDATA\[([\s\S]*?)\]\]>$/, "$1").trim() : "";
}
function strip(s: string): string {
  return s.replace(/<[^>]+>/g, " ").replace(/&[a-z]+;/gi, " ").replace(/\s+/g, " ").trim();
}

