export async function searchDuckDuckGo(query: string): Promise<WebResult[]> {
  startSearchWatchdog();
  const q = query.trim();
  const sec = ["cve","exploit","malware","ransomware","breach","vulnerability","apt","attack","phishing","hack","zero-day","security","threat","cyber"];
  const searchQ = sec.some(t => q.toLowerCase().includes(t)) ? q : `${q} cybersecurity`;
  const enc = encodeURIComponent(searchQ);

  const seen = new Set<string>();
  const allResults: WebResult[] = [];
  const addResults = (items: WebResult[]) => {
    for (const item of items) {
      if (item.link && !seen.has(item.link)) { seen.add(item.link); allResults.push(item); }
    }
  };

  // Permanent fix: use our server-side Edge Function for web search.
  // This avoids browser CORS issues and "all proxies down" failures in production.
  try {
    const { data, error } = await supabase.functions.invoke("online-search", {
      body: { query: searchQ, num: 10 },
    });
    if (!error && data?.sources?.length) {
      const fromEdge: WebResult[] = (data.sources as any[]).slice(0, 12).map((s, i) => ({
        position: i + 1,
        title: String(s.title || "").trim() || "Untitled result",
        link: String(s.link || "").trim(),
        snippet: String(s.snippet || "").trim().slice(0, 300),
        source: String(s.source || hostOf(s.link || "") || "unknown"),
        badge: "Web",
      })).filter(r => r.link?.startsWith("http"));
      if (fromEdge.length) return rankResults(fromEdge);
    }
  } catch {
    // fall through to legacy multi-engine fallback below
  }

  // Engine 1: Google News RSS — try all CORS proxies, first working one wins
  const GURL = `https://news.google.com/rss/search?q=${enc}&hl=en-US&gl=US&ceid=US:en`;
  const googleXml = await (async () => {
    const proxies = healthyProxies();
    for (const proxy of proxies) {
      const proxyUrl = proxy.endsWith("=") ? `${proxy}${encodeURIComponent(GURL)}` : `${proxy}${GURL}`;
      let text = await fetchHtml(proxyUrl, 9000);
      if (!text) { markProxy(proxy, false); continue; }
      if (text.trimStart().startsWith("{")) { try { text = JSON.parse(text).contents || text; } catch {} }
      if (text.includes("<item")) { markProxy(proxy, true); return text; }
    }
    return "";
  })();
  if (googleXml) addResults(parseRSS(googleXml, "Google News"));

  // Engine 2: Bing News RSS via CORS proxies
  const BURL = `https://www.bing.com/news/search?q=${enc}&format=RSS`;
  const bingXml = await (async () => {
    const proxies = healthyProxies();
    for (const proxy of proxies) {
      const proxyUrl = proxy.endsWith("=") ? `${proxy}${encodeURIComponent(BURL)}` : `${proxy}${BURL}`;
      let text = await fetchHtml(proxyUrl, 9000);
      if (!text) { markProxy(proxy, false); continue; }
      if (text.trimStart().startsWith("{")) { try { text = JSON.parse(text).contents || text; } catch {} }
      if (text.includes("<item")) { markProxy(proxy, true); return text; }
    }
    return "";
  })();
  if (bingXml.includes("<item")) addResults(parseRSS(bingXml, "Bing News"));

  // Engine 3: SearXNG — skip instances marked as down
  if (allResults.length < 5) {
    const healthySearx = SEARXNG.filter(isProxyHealthy);
    for (let i = 0; i < healthySearx.length; i += 4) {
      const batch = healthySearx.slice(i, i + 4);
      const result = await Promise.any(batch.map(async base => {
        const html = await fetchHtml(`${base}/search?q=${enc}&format=json&language=en&categories=news,it,general&time_range=month`, 4000);
        if (!html) { markProxy(base, false); throw new Error("empty"); }
        try {
          const d = JSON.parse(html);
          if (!Array.isArray(d?.results) || d.results.length < 2) { markProxy(base, false); throw new Error("few"); }
          markProxy(base, true);
          return d.results.filter((r: any) => r.title && r.url).slice(0,10).map((r: any,i:number) => ({
            position: i+1, title: String(r.title).trim(), link: String(r.url).trim(),
            snippet: String(r.content||"").trim().slice(0,300), source: hostOf(r.url), badge: "Web",
          })) as WebResult[];
        } catch { markProxy(base, false); throw new Error("parse"); }
      })).catch(() => null);
      if (result?.length) { addResults(result); break; }
    }
  }

  // Engine 4: DDG Instant Answer — always free, no proxy, no key needed
  const ddgResult = await (async () => {
    try {
      // IMPORTANT: browser CORS is unreliable for api.duckduckgo.com in some environments.
      // Always fetch via a healthy proxy (prefer our Supabase proxy).
      const DDG = `https://api.duckduckgo.com/?q=${enc}&format=json&no_redirect=1&no_html=1&skip_disambig=1`;
      let jsonText = "";
      for (const proxy of healthyProxies()) {
        const proxyUrl = proxy.endsWith("=") ? `${proxy}${encodeURIComponent(DDG)}` : `${proxy}${DDG}`;
        const t = await fetchHtml(proxyUrl, 7000);
        if (!t) { markProxy(proxy, false); continue; }
        markProxy(proxy, true);
        jsonText = t;
        break;
      }
      if (!jsonText) return [] as WebResult[];
      const d = JSON.parse(jsonText);
      const items: WebResult[] = [];
      if (d.AbstractURL && d.AbstractText?.length > 30)
        items.push({ position:1, title:d.Heading||q, link:d.AbstractURL, snippet:d.AbstractText.slice(0,300), source:d.AbstractSource||"DDG", badge:"DDG" });
      for (const topic of (d.RelatedTopics||[]).slice(0,8))
        if (topic.FirstURL && topic.Text?.length > 20)
          items.push({ position:items.length+1, title:topic.Text.slice(0,100), link:topic.FirstURL, snippet:topic.Text.slice(0,200), source:hostOf(topic.FirstURL), badge:"DDG" });
      return items;
    } catch { return [] as WebResult[]; }
  })();
  addResults(ddgResult);

  // If all engines fail — return a direct Google search link so user is never stuck
  if (allResults.length === 0) {
    return [{ position:1, title:`Search "${q}" on Google`, link:`https://www.google.com/search?q=${enc}`, snippet:`All search engines temporarily unreachable. Click to search Google directly.`, source:"google.com", badge:"Fallback" }];
  }

  return rankResults(allResults);
}


// ── 2. NVD CVE search ─────────────────────────────────────────────────────────
async function searchNVD(query: string): Promise<WebResult[]> {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 15000);
    const res = await fetch(
      `https://services.nvd.nist.gov/rest/json/cves/2.0?keywordSearch=${encodeURIComponent(query)}&resultsPerPage=6`,
      { signal: ctrl.signal }
    );
    clearTimeout(t);
    if (!res.ok) return [];
    const d = await res.json();
    if (!d?.vulnerabilities?.length) return [];
    return d.vulnerabilities.map(({ cve }: any, i: number) => {
      const desc = cve.descriptions?.find((x: any) => x.lang === "en")?.value || "";
      const score = cve.metrics?.cvssMetricV31?.[0]?.cvssData?.baseScore
                 ?? cve.metrics?.cvssMetricV30?.[0]?.cvssData?.baseScore;
      return {
        position: i + 1,
        title: `${cve.id}: ${desc.slice(0, 120)}`,
        link: `https://nvd.nist.gov/vuln/detail/${cve.id}`,
        snippet: desc.slice(0, 280),
        source: "NVD / NIST",
        badge: "CVE",
        severity: score ? (score >= 9 ? "critical" : score >= 7 ? "high" : score >= 4 ? "medium" : "low") : undefined,
      };
    }).filter((r: WebResult) => relevanceScore(query, `${r.title} ${r.snippet}`) >= 35);
  } catch { return []; }
}

// ── 3. ThreatFox IOC search — high confidence only, directly related ──────────
async function searchThreatFox(query: string): Promise<WebResult[]> {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 10000);
    const res = await fetch("https://threatfox-api.abuse.ch/api/v1/", {
      method: "POST",
      signal: ctrl.signal,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query: "search_ioc", search_term: query }),
    });
    clearTimeout(t);
    if (!res.ok) return [];
    const d = await res.json();
    if (d?.query_status !== "ok" || !Array.isArray(d.data)) return [];
    const qLower = query.toLowerCase();
    return d.data
      // Only show high-confidence IOCs directly related to the query
      .filter((ioc: any) =>
        (ioc.confidence_level || 0) >= 75 &&
        ((ioc.malware_printable || "").toLowerCase().includes(qLower) ||
         (ioc.tags || []).some((t: string) => t.toLowerCase().includes(qLower)) ||
         (ioc.ioc || "").toLowerCase().includes(qLower))
      )
      .slice(0, 5)
      .map((ioc: any, i: number) => ({
        position: i + 1,
        title: `${ioc.malware_printable || "IOC"} — ${ioc.ioc_type}: ${(ioc.ioc || "").slice(0, 80)}`,
        link: `https://threatfox.abuse.ch/ioc/${ioc.id}/`,
        snippet: `Threat: ${ioc.threat_type_desc || ioc.threat_type} · Confidence: ${ioc.confidence_level}% · Tags: ${(ioc.tags || []).join(", ") || "none"}`,
        source: "ThreatFox",
        badge: "IOC",
        severity: (ioc.confidence_level || 0) >= 90 ? "critical" : "high",
      }));
  } catch { return []; }
}

// ── 4. GitHub Security Advisories ─────────────────────────────────────────────
async function searchGitHub(query: string): Promise<WebResult[]> {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), 10000);
    // GitHub advisories API ignores free-text query in some cases; pull recent then filter ourselves.
    const res = await fetch(
      `https://api.github.com/advisories?per_page=40&sort=published&direction=desc`,
      { signal: ctrl.signal, headers: { Accept: "application/vnd.github+json" } }
    );
    clearTimeout(t);
    if (!res.ok) return [];
    const d = await res.json();
    if (!Array.isArray(d)) return [];
    return d.map((a: any, i: number) => ({
      position: i + 1,
      title: `${a.ghsa_id}: ${(a.summary || "").slice(0, 120)}`,
      link: a.html_url || `https://github.com/advisories/${a.ghsa_id}`,
      snippet: (a.description || a.summary || "").slice(0, 280),
      source: "GitHub Advisories",
      badge: "GHSA",
      severity: a.severity,
    }))
      .filter((r: WebResult) => relevanceScore(query, `${r.title} ${r.snippet}`) >= 45)
      .slice(0, 5);
  } catch { return []; }
}

// ── 5. Internal DB ─────────────────────────────────────────────────────────────
async function searchInternal(query: string): Promise<any[]> {
  const { data } = await supabase
    .from("threat_items")
    .select("id,title,link,excerpt,severity,published_at,source_name")
    .or(`title.ilike.%${query}%,excerpt.ilike.%${query}%`)
    .order("published_at", { ascending: false })
    .limit(15);
  return (data || []).filter((i: any) => relevanceScore(query, `${i.title} ${i.excerpt || ""} ${i.source_name}`) >= 35);
}

