    if (t.includes("IMPACT"))    return { bg: "bg-red-500/5",    label: "text-red-400",    icon: "💥" };
    if (t.includes("TRENDS"))    return { bg: "bg-blue-400/5",   label: "text-blue-400",   icon: "📈" };
