// ── Main page ──────────────────────────────────────────────────────────────────
export default function OnlineSearchPage() {
  const [searchParams] = useSearchParams();
  const [query, setQuery] = useState(() => searchParams.get("q") || "");
  const [loading, setLoading] = useState(false);
  const [webResults, setWebResults] = useState<WebResult[]>([]);
  const [intelResults, setIntelResults] = useState<WebResult[]>([]);
  const [internalHits, setInternalHits] = useState<any[]>([]);
  const [webLoading, setWebLoading] = useState(false);
  const [searched, setSearched] = useState(false);
  const [searchKey, setSearchKey] = useState(0); // incremented on each search to remount AI panel
  const inputRef = useRef<HTMLInputElement>(null);
  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);
  const runIdRef = useRef(0);

  const runSearch = useCallback(async (term: string) => {
    if (!term.trim()) return;
    const runId = ++runIdRef.current;
    setLoading(true);
    setSearched(true);
    setWebResults([]); setIntelResults([]); setInternalHits([]);
    setSearchKey(k => k + 1); // remount AI panel for fresh generation

    // Internal DB — fastest, show immediately
    searchInternal(term).then((hits) => {
      if (runId === runIdRef.current) setInternalHits(hits);
    });

    // NVD + ThreatFox + GitHub — fast APIs
    Promise.all([searchNVD(term), searchThreatFox(term), searchGitHub(term)]).then(([nvd, tf, gh]) => {
      if (runId !== runIdRef.current) return;
      const seen = new Set<string>();
      const merged: WebResult[] = [];
      for (const r of [...nvd, ...gh, ...tf]) {
        if (!seen.has(r.link)) { seen.add(r.link); merged.push({ ...r, position: merged.length + 1 }); }
      }
      setIntelResults(merged);
    });

    // DuckDuckGo web scrape — takes longer
    setWebLoading(true);
    searchDuckDuckGo(term).then(results => {
      if (runId !== runIdRef.current) return;
      setWebResults(results);
      setWebLoading(false);
    });

    setLoading(false);
  }, []);

  // Auto-search from URL param
  useEffect(() => {
    const q = searchParams.get("q");
    if (q) { setQuery(q); runSearch(q); }
  }, []);

  // Live search as you type (debounced 600ms)
  function handleInput(val: string) {
    setQuery(val);
    if (debounce.current) clearTimeout(debounce.current);
    if (val.trim().length >= 3) {
      debounce.current = setTimeout(() => runSearch(val), 600);
    }
  }

  const EXAMPLES = ["Log4Shell", "CVE-2024-3400", "Volt Typhoon", "LockBit ransomware", "Scattered Spider", "APT28", "supply chain attack"];

  return (
    <div className="container mx-auto max-w-5xl px-4 py-8">
      {/* Header */}
      <div className="mb-6">
        <h1 className="text-xl font-bold tracking-tight flex items-center gap-2 mb-1">
          <Search className="h-5 w-5 text-primary" /> Online Threat Search
        </h1>
        <p className="text-sm text-muted-foreground">
          Live results from DuckDuckGo · NVD · ThreatFox · GitHub · Internal DB — auto-searches as you type
        </p>
      </div>

      {/* Search bar */}
      <div className="flex gap-2 mb-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
          <Input
            ref={inputRef}
            value={query}
            onChange={e => handleInput(e.target.value)}
            onKeyDown={e => e.key === "Enter" && runSearch(query)}
            placeholder="Search threats, CVEs, malware, actors… results appear as you type"
            className="pl-9 h-11 text-sm"
            autoFocus
          />
          {query && <button onClick={() => { setQuery(""); setWebResults([]); setIntelResults([]); setInternalHits([]); setSearched(false); }} className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-muted-foreground hover:text-foreground">✕</button>}
        </div>
        <Button onClick={() => runSearch(query)} disabled={!query.trim()} className="h-11 px-5 gap-2">
          {loading ? <RefreshCw className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}
          Search
        </Button>
      </div>

      {/* Quick examples */}
      {!searched && (
        <div className="flex flex-wrap gap-2 mb-6 items-center">
          <span className="text-xs text-muted-foreground">Try:</span>
          {EXAMPLES.map(ex => (
            <button key={ex} onClick={() => { setQuery(ex); runSearch(ex); }}
              className="rounded-full border border-border/50 px-3 py-0.5 text-xs text-muted-foreground hover:border-primary/40 hover:text-foreground transition-colors">
              {ex}
            </button>
          ))}
        </div>
      )}

      {/* Results */}
      {searched && (
        <div className="space-y-6">
          {/* ── AI CTI Summary — synthesises ALL sources automatically ──────── */}
          <AISummaryPanel
            key={searchKey}
            query={query}
            internalHits={internalHits}
            webResults={webResults}
            intelResults={intelResults}
          />

          {/* Internal DB — instant */}
          {internalHits.length > 0 && (
            <section>
              <div className="flex items-center gap-2 mb-3">
                <Database className="h-4 w-4 text-primary" />
                <h2 className="text-sm font-bold uppercase tracking-widest">Your Threat Database</h2>
                <div className="h-px flex-1 bg-border/40" />
                <span className="text-xs text-muted-foreground">{internalHits.length} matches</span>
              </div>
              <div className="space-y-2">
                {internalHits.map((item: any) => (
                  <a key={item.id} href={item.link} target="_blank" rel="noopener noreferrer"
                    className="flex items-start gap-3 rounded-lg border border-border/50 bg-card/60 px-4 py-3 hover:border-primary/40 hover:bg-card/80 transition-all group">
                    <span className={`shrink-0 text-[9px] font-bold px-1.5 py-0.5 rounded border mt-0.5 ${SEV_COLOR[item.severity] || "border-border/40 text-muted-foreground"}`}>
                      {(item.severity || "?").toUpperCase()}
                    </span>
                    <div className="flex-1 min-w-0">
                      <div className="text-sm font-medium group-hover:text-primary transition-colors line-clamp-2">{item.title}</div>
                      <div className="text-[10px] text-muted-foreground mt-0.5 flex gap-2">
                        <span className="font-medium">{item.source_name}</span>
                        {item.excerpt && <span>· {item.excerpt.slice(0, 80)}…</span>}
                      </div>
                    </div>
                    <ExternalLink className="h-3.5 w-3.5 shrink-0 mt-0.5 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity" />
                  </a>
                ))}
              </div>
            </section>
          )}

          {/* DuckDuckGo web results */}
          <section>
            <div className="flex items-center gap-2 mb-3">
              <Globe className="h-4 w-4 text-primary" />
              <h2 className="text-sm font-bold uppercase tracking-widest">DuckDuckGo Web Results</h2>
              <div className="h-px flex-1 bg-border/40" />
              {webLoading
                ? <span className="text-xs text-muted-foreground flex items-center gap-1"><RefreshCw className="h-3 w-3 animate-spin" /> Searching…</span>
                : <span className="text-xs text-muted-foreground">{webResults.length} results</span>}
            </div>
            {webLoading && webResults.length === 0 && (
              <div className="rounded-lg border border-border/40 bg-card/40 px-4 py-6 text-center text-sm text-muted-foreground">
                <RefreshCw className="h-4 w-4 animate-spin mx-auto mb-2 text-primary" />
                Scraping DuckDuckGo for live results…
              </div>
            )}
            {!webLoading && webResults.length === 0 && searched && (
              <div className="rounded-lg border border-border/40 bg-card/40 px-4 py-4 text-sm text-muted-foreground text-center">
                No web results found. Try a different keyword.
              </div>
            )}
            <div className="space-y-2">
              {webResults.map((r, i) => <ResultCard key={i} r={r} />)}
            </div>
          </section>

          {/* Intel results (NVD + ThreatFox + GitHub) */}
          {intelResults.length > 0 && (
            <section>
              <div className="flex items-center gap-2 mb-3">
                <Shield className="h-4 w-4 text-primary" />
                <h2 className="text-sm font-bold uppercase tracking-widest">Threat Intelligence (NVD · ThreatFox · GitHub)</h2>
                <div className="h-px flex-1 bg-border/40" />
                <span className="text-xs text-muted-foreground">{intelResults.length} results</span>
              </div>
              <div className="space-y-2">
                {intelResults.map((r, i) => <ResultCard key={i} r={r} />)}
              </div>
            </section>
          )}

          {!internalHits.length && !webResults.length && !intelResults.length && !webLoading && (
            <div className="text-center py-16 text-muted-foreground text-sm">
              No results for "<strong>{query}</strong>". Try a broader term.
            </div>
          )}
        </div>
      )}
    </div>
  );
}
